-- Additive SOURCE CANDIDATE: source-bound independently reviewed catalyst protocol.
-- Structural acceptance is not external semantic truth/formal model approval.
-- No model calls, binding-row mutation, old ACL changes or budget/deadline changes.
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL statement_timeout='30s';SET LOCAL lock_timeout='2s';
SELECT pg_advisory_xact_lock(64221022);
DO $candidate$
DECLARE targets oid[]:=ARRAY[to_regprocedure('public.vnext_thesis_command_v1(text,text,jsonb)')::oid,to_regprocedure('public.vnext_thesis_project_v1(jsonb)')::oid,to_regprocedure('public.vnext_provider_command_v1(text,text,jsonb)')::oid];
 additions oid[]:=ARRAY[]::oid[];before_namespace jsonb;after_namespace jsonb;constraint_metadata jsonb;constraint_definition text;spec record;target oid;source text;changed text;definition text;metadata jsonb;
 catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND NOT(p.oid=ANY($2))),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace AND NOT(c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check')),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' OR array_position(targets,NULL) IS NOT NULL THEN RAISE EXCEPTION 'vnext_catalyst_prerequisites_missing';END IF;
 IF to_regprocedure('public.vnext_semantic_criteria_current_v1(uuid,text)') IS NOT NULL OR to_regprocedure('public.vnext_current_deep_score_v1(jsonb,uuid,text)') IS NOT NULL THEN RAISE EXCEPTION 'vnext_catalyst_first_install_required';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='stockinsider_vnext_owner' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls) THEN RAISE EXCEPTION 'vnext_catalyst_owner_changed';END IF;
 FOR spec IN SELECT * FROM(VALUES
 ('public.vnext_deep_score_v1(jsonb)','12b3cf00b3558c1e80008c7ba905e6482e7c9ef4fc7f5f50df71fd644a27044c'),
 ('public.vnext_provider_command_v1(text,text,jsonb)','0e8121100eb0781d27e46f54d667cce39bbd061daa05a10efc4ebbb29a0312bd'),
 ('public.vnext_input_sources_current_v1(jsonb,text)','83c21c7f7247045c0fe8f66d8d6ae5dbc88c72286ef38274ca8d8a11fe9ca352'),
 ('public.vnext_source_evidence_current_v1(jsonb,text)','712c701f18809a44fb788453e5e12a9d98b93f28ee3573973606d94bb739f0e8')) dependency(signature,body_hash) LOOP
  IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure(spec.signature) AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=spec.body_hash) THEN RAISE EXCEPTION 'vnext_catalyst_dependency_changed:%',spec.signature;END IF;
 END LOOP;
 SELECT pg_get_constraintdef(c.oid),to_jsonb(c)-'oid'-'conbin' INTO constraint_definition,constraint_metadata FROM pg_constraint c WHERE c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check';
 IF obj_description((SELECT c.oid FROM pg_constraint c WHERE c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check'),'pg_constraint') IS NOT NULL OR constraint_definition IS DISTINCT FROM 'CHECK ((prompt_version = ANY (ARRAY[''vnext-research-worker-v1''::text, ''vnext-research-worker-v2''::text])))' THEN RAISE EXCEPTION 'vnext_catalyst_prompt_constraint_predecessor';END IF;
 EXECUTE catalog_sql INTO before_namespace USING targets,additions;
 EXECUTE $create_vnext_semantic_criteria_current_v1$CREATE FUNCTION public.vnext_semantic_criteria_current_v1(p_revision uuid,p_input_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE pub public.vnext_publications_v1; job public.vnext_jobs_v1; frozen jsonb; author_call public.vnext_provider_invocations_v1; reviewer_call public.vnext_provider_invocations_v1; author_input jsonb; reviewer_input jsonb;
 claim jsonb; annotation jsonb; checked jsonb; assessment jsonb; evidence jsonb; extraction public.vnext_extractions_v1; criterion text; statement text; quote text; identity_text text; start_cp integer; end_cp integer; catalyst_day date; known_day date:=(statement_timestamp() AT TIME ZONE 'Asia/Taipei')::date; published_day date; event_hash text; same_event text; annotation_hash text; criteria jsonb:='[]'::jsonb; met boolean; gap text;
BEGIN
 IF p_revision IS NULL OR coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF;
 SELECT * INTO pub FROM public.vnext_publications_v1 WHERE revision_id=p_revision;
 SELECT * INTO job FROM public.vnext_jobs_v1 WHERE job_id=pub.job_id;
 SELECT preparation.evidence INTO frozen FROM public.vnext_preparations_v1 preparation WHERE preparation.job_id=pub.job_id;
 IF pub.revision_id IS NULL OR pub.input_hash IS DISTINCT FROM p_input_hash OR job.state IS DISTINCT FROM 'published' OR job.symbol IS DISTINCT FROM pub.symbol OR job.input_hash IS DISTINCT FROM pub.input_hash OR pub.content IS DISTINCT FROM job.author_result
  OR NOT EXISTS(SELECT FROM public.vnext_members_v1 member WHERE member.symbol=pub.symbol AND member.state<>'exited' AND member.contraindication IS FALSE AND member.input_hash=pub.input_hash)
  OR EXISTS(SELECT FROM public.vnext_publications_v1 newer WHERE newer.symbol=pub.symbol AND (newer.published_at,newer.revision_id)>(pub.published_at,pub.revision_id))
  OR public.vnext_input_sources_current_v1(frozen,pub.symbol) IS DISTINCT FROM true OR job.sources_read_at IS NULL OR job.author_principal IS NULL OR job.reviewer_principal IS NULL OR job.author_principal=job.reviewer_principal OR job.execution_id IS NULL OR job.reviewer_execution IS NULL OR job.execution_id=job.reviewer_execution
  OR job.reviewer_result->>'approved' IS DISTINCT FROM 'true' OR job.reviewer_result->>'authorOutputHash' IS DISTINCT FROM job.author_result->>'outputHash' THEN RETURN NULL; END IF;
 SELECT * INTO author_call FROM public.vnext_provider_invocations_v1 WHERE job_id=job.job_id AND task='author';
 SELECT * INTO reviewer_call FROM public.vnext_provider_invocations_v1 WHERE job_id=job.job_id AND task='reviewer';
 IF author_call.invocation_id IS NULL OR reviewer_call.invocation_id IS NULL OR author_call.invocation_id=reviewer_call.invocation_id OR author_call.state IS DISTINCT FROM 'completed' OR reviewer_call.state IS DISTINCT FROM 'completed'
  OR author_call.provider IS DISTINCT FROM 'openai-responses' OR reviewer_call.provider IS DISTINCT FROM 'openai-responses' OR coalesce(author_call.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR coalesce(reviewer_call.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR author_call.provider_response_id=reviewer_call.provider_response_id
  OR author_call.prompt_version IS DISTINCT FROM 'vnext-research-worker-v3' OR reviewer_call.prompt_version IS DISTINCT FROM 'vnext-research-worker-v3'
  OR author_call.principal IS DISTINCT FROM job.author_principal OR reviewer_call.principal IS DISTINCT FROM job.reviewer_principal OR author_call.execution_id IS DISTINCT FROM job.execution_id OR reviewer_call.execution_id IS DISTINCT FROM job.reviewer_execution
  OR author_call.input_hash IS DISTINCT FROM job.input_hash OR reviewer_call.input_hash IS DISTINCT FROM job.input_hash OR author_call.normalized_output IS DISTINCT FROM job.author_result OR reviewer_call.normalized_output IS DISTINCT FROM job.reviewer_result
  OR author_call.settled_at IS NULL OR reviewer_call.settled_at IS NULL OR author_call.settled_at<author_call.started_at OR reviewer_call.settled_at<reviewer_call.started_at OR author_call.settled_at>author_call.deadline_at OR reviewer_call.settled_at>reviewer_call.deadline_at
  OR job.sources_read_at<author_call.settled_at OR job.sources_read_at>reviewer_call.started_at OR pub.published_at<reviewer_call.settled_at
  OR author_call.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(author_call.frozen_request),'UTF8')),'hex') OR reviewer_call.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(reviewer_call.frozen_request),'UTF8')),'hex')
  OR encode(sha256(convert_to(author_call.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM 'e9fd13b01b3d961cd612f1ef44136f07b7538ebcaae6142f2cedf21d96877803' OR encode(sha256(convert_to(reviewer_call.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM '9c5d0ccd2ef984d9924bf92eb59a70a3ba1bccdefb3d1086b783570d67f96f69'
  OR author_call.frozen_request->>'model' IS DISTINCT FROM author_call.model OR reviewer_call.frozen_request->>'model' IS DISTINCT FROM reviewer_call.model THEN RETURN NULL; END IF;
 author_input:=(author_call.frozen_request->>'input')::jsonb;reviewer_input:=(reviewer_call.frozen_request->>'input')::jsonb;
 IF author_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','author','jobId',job.job_id,'executionId',job.execution_id,'inputHash',job.input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol) OR reviewer_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','reviewer','jobId',job.job_id,'executionId',job.reviewer_execution,'inputHash',job.input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol,'authorArtifact',job.author_result) THEN RETURN NULL;END IF;
 IF author_input->>'jobId' IS DISTINCT FROM job.job_id::text OR reviewer_input->>'jobId' IS DISTINCT FROM job.job_id::text OR author_input->>'executionId' IS DISTINCT FROM job.execution_id::text OR reviewer_input->>'executionId' IS DISTINCT FROM job.reviewer_execution::text
  OR author_input->>'symbol' IS DISTINCT FROM job.symbol OR reviewer_input->>'symbol' IS DISTINCT FROM job.symbol OR author_input->>'task' IS DISTINCT FROM 'author' OR reviewer_input->>'task' IS DISTINCT FROM 'reviewer' OR author_input->>'inputHash' IS DISTINCT FROM job.input_hash OR reviewer_input->>'inputHash' IS DISTINCT FROM job.input_hash
  OR author_input->'evidence' IS DISTINCT FROM jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence') OR reviewer_input->'evidence' IS DISTINCT FROM author_input->'evidence' OR reviewer_input->'authorArtifact' IS DISTINCT FROM job.author_result THEN RETURN NULL; END IF;
 FOREACH criterion IN ARRAY ARRAY['catalyst_dated','catalyst_verified','catalyst_mechanism_documented','catalyst_falsifier_defined'] LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(job.author_result->'claims') candidate WHERE candidate->'semantic'->>'criterion'=criterion)<>1 THEN RETURN NULL; END IF;
  SELECT value INTO claim FROM jsonb_array_elements(job.author_result->'claims') WHERE value->'semantic'->>'criterion'=criterion;annotation:=claim->'semantic';
  IF jsonb_typeof(annotation) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
  IF EXISTS(SELECT FROM unnest(ARRAY['schemaVersion','criterion','outcome','symbol','evidenceId','contentHash','field','quote','catalystAt','catalystIdentity']) annotation_field WHERE jsonb_typeof(annotation->annotation_field) IS DISTINCT FROM 'string') THEN RETURN NULL;END IF;
  IF NOT(annotation ?& ARRAY['schemaVersion','criterion','outcome','symbol','evidenceId','contentHash','field','startCp','endCp','quote','catalystAt','catalystIdentity']) OR (SELECT count(*) FROM jsonb_object_keys(annotation))<>12
   OR annotation->>'schemaVersion' IS DISTINCT FROM 'vnext-catalyst-annotation-v1' OR annotation->>'symbol' IS DISTINCT FROM pub.symbol OR annotation->>'criterion' IS DISTINCT FROM criterion OR annotation->>'field' IS DISTINCT FROM 'statement'
   OR coalesce(annotation->>'outcome','') NOT IN('met','not_met','unknown') OR claim->>'kind' IS DISTINCT FROM 'assumption' OR claim ? 'numeric' OR NOT(claim->'evidenceIds' ? (annotation->>'evidenceId')) THEN RETURN NULL; END IF;
  SELECT value INTO evidence FROM jsonb_array_elements(frozen->'evidence') WHERE value->>'id'=annotation->>'evidenceId';
  IF evidence IS NULL OR evidence->>'key' IS DISTINCT FROM 'reported_event' OR evidence->>'kind' IS DISTINCT FROM 'assumption' OR evidence->>'sourceTier' IS DISTINCT FROM 'public' OR evidence->>'contentHash' IS DISTINCT FROM annotation->>'contentHash'
   OR evidence->'value'->>'scope' IS DISTINCT FROM 'official_original' OR evidence->'value'->>'originSource' IS DISTINCT FROM 'official' OR evidence->'value'->>'claimStatus' IS DISTINCT FROM 'reported' OR coalesce(evidence->'value'->>'eventBasis','') NOT IN('source_publication','original_event')
   OR public.vnext_source_evidence_current_v1(evidence,pub.symbol) IS DISTINCT FROM true THEN RETURN NULL; END IF;
  SELECT * INTO extraction FROM public.vnext_extractions_v1 source_receipt WHERE source_receipt.content_hash=evidence->>'contentHash' AND source_receipt.scope='official_original' AND source_receipt.state='completed' AND source_receipt.extraction->'evidence'=evidence;
  IF extraction.content_hash IS NULL OR NOT(extraction.original->'symbols' ? pub.symbol) OR extraction.original->>'body' IS DISTINCT FROM evidence->'value'->>'statement' OR extraction.original->>'publishedAt' IS DISTINCT FROM evidence->'value'->>'publishedAt' THEN RETURN NULL; END IF;
  statement:=extraction.original->>'body';
  IF jsonb_typeof(annotation->'quote') IS DISTINCT FROM 'string' OR jsonb_typeof(annotation->'catalystIdentity') IS DISTINCT FROM 'string' OR jsonb_typeof(annotation->'catalystAt') IS DISTINCT FROM 'string'
   OR jsonb_typeof(annotation->'startCp') IS DISTINCT FROM 'number' OR jsonb_typeof(annotation->'endCp') IS DISTINCT FROM 'number' OR coalesce(annotation->>'startCp','') !~ '^[0-9]+$' OR coalesce(annotation->>'endCp','') !~ '^[0-9]+$' THEN RETURN NULL; END IF;
  IF (annotation->>'startCp')::numeric<0 OR (annotation->>'endCp')::numeric>(char_length(statement)) OR (annotation->>'startCp')::numeric>=(annotation->>'endCp')::numeric THEN RETURN NULL; END IF;
  start_cp:=(annotation->>'startCp')::integer;end_cp:=(annotation->>'endCp')::integer;quote:=annotation->>'quote';identity_text:=annotation->>'catalystIdentity';
  IF char_length(quote) NOT BETWEEN 12 AND 1024 OR char_length(identity_text) NOT BETWEEN 12 AND 160 OR identity_text IS DISTINCT FROM btrim(identity_text) OR substring(statement FROM start_cp+1 FOR end_cp-start_cp) IS DISTINCT FROM quote
   OR strpos(quote,identity_text)=0 OR strpos(statement,identity_text)=0 OR strpos(substring(statement FROM strpos(statement,identity_text)+1),identity_text)>0 THEN RETURN NULL; END IF;
  IF annotation->>'catalystAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN NULL; END IF;
  BEGIN catalyst_day:=(annotation->>'catalystAt')::date;EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN NULL;END;
  IF to_char(catalyst_day,'YYYY-MM-DD') IS DISTINCT FROM annotation->>'catalystAt' THEN RETURN NULL; END IF;
  published_day:=((extraction.original->>'publishedAt')::timestamptz AT TIME ZONE 'Asia/Taipei')::date;
  IF catalyst_day<known_day OR catalyst_day<published_day OR catalyst_day>(known_day+interval '3 months')::date OR catalyst_day>(published_day+interval '3 months')::date THEN RETURN NULL; END IF;
  IF criterion IN('catalyst_dated','catalyst_verified') AND NOT(quote ~ ('(^|[^0-9])'||(annotation->>'catalystAt')||'([^0-9]|$)')) THEN RETURN NULL; END IF;
  annotation_hash:=encode(sha256(convert_to(public.vnext_catalog_canonical_v1(annotation),'UTF8')),'hex');
  event_hash:=encode(sha256(convert_to(public.vnext_catalog_canonical_v1(jsonb_build_object('symbol',pub.symbol,'contentHash',extraction.content_hash,'catalystAt',annotation->>'catalystAt','catalystIdentity',identity_text)),'UTF8')),'hex');
  IF same_event IS NOT NULL AND same_event<>event_hash THEN RETURN NULL; END IF;same_event:=event_hash;
  IF (SELECT count(*) FROM jsonb_array_elements(job.reviewer_result->'claimChecks') check_row WHERE check_row->>'claimId'=claim->>'id')<>1 THEN RETURN NULL; END IF;
  SELECT value INTO checked FROM jsonb_array_elements(job.reviewer_result->'claimChecks') WHERE value->>'claimId'=claim->>'id';assessment:=checked->'semanticAssessment';
  IF checked->>'verdict' IS DISTINCT FROM 'supported' OR NOT EXISTS(SELECT FROM jsonb_array_elements(checked->'sources') source_row WHERE source_row->>'id'=evidence->>'id' AND source_row->>'contentHash'=evidence->>'contentHash') OR jsonb_typeof(assessment) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
  IF NOT(assessment ?& ARRAY['schemaVersion','annotation','assessment','reason']) OR (SELECT count(*) FROM jsonb_object_keys(assessment))<>4 OR assessment->>'schemaVersion' IS DISTINCT FROM 'vnext-catalyst-assessment-v1' OR assessment->'annotation' IS DISTINCT FROM annotation
   OR jsonb_typeof(assessment->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(assessment->>'reason')) NOT BETWEEN 20 AND 2000 OR coalesce(assessment->>'assessment','') NOT IN('supported_report','supported_inference','insufficient')
   OR criterion IN('catalyst_dated','catalyst_verified') AND assessment->>'assessment'='supported_inference'
   OR criterion IN('catalyst_mechanism_documented','catalyst_falsifier_defined') AND assessment->>'assessment'='supported_report'
   OR assessment->>'assessment'='insufficient' AND annotation->>'outcome'<>'unknown' THEN RETURN NULL; END IF;
  gap:=CASE WHEN assessment->>'assessment'='insufficient' THEN 'criterion_assessment_insufficient' WHEN annotation->>'outcome'='unknown' THEN 'criterion_outcome_unknown' WHEN criterion='catalyst_verified' AND annotation->>'outcome'='met' THEN 'independent_confirmation_missing' ELSE NULL END;
  met:=CASE WHEN gap IS NOT NULL THEN NULL ELSE annotation->>'outcome'='met' END;
  criteria:=criteria||jsonb_build_array(jsonb_build_object('criterion',criterion,'annotationHash',annotation_hash,'eventIdentityHash',event_hash,'sourceId',evidence->>'id','sourceHash',evidence->>'contentHash','validFrom',extraction.original->>'publishedAt','validUntil',to_char((((catalyst_day+1)::timestamp AT TIME ZONE 'Asia/Taipei')-interval '1 millisecond') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'met',met,'gap',gap));
 END LOOP;
 RETURN jsonb_build_object('schemaVersion','vnext-catalyst-receipt-v1','revisionId',pub.revision_id,'inputHash',pub.input_hash,'symbol',pub.symbol,'authorInvocation',author_call.invocation_id,'reviewerInvocation',reviewer_call.invocation_id,'authorExecution',job.execution_id,'reviewerExecution',job.reviewer_execution,'criteria',criteria);
END
;$function$;$create_vnext_semantic_criteria_current_v1$;
 ALTER FUNCTION public.vnext_semantic_criteria_current_v1 (uuid,text) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_semantic_criteria_current_v1 (uuid,text) FROM PUBLIC,anon,authenticated,service_role;
 EXECUTE $create_vnext_current_deep_score_v1$CREATE FUNCTION public.vnext_current_deep_score_v1(input jsonb,p_revision uuid,p_input_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$
DECLARE base jsonb; receipt jsonb; met_count integer; factor_value numeric;
BEGIN
 base:=public.vnext_deep_score_v1(input);
 receipt:=public.vnext_semantic_criteria_current_v1(p_revision,p_input_hash);
 IF receipt IS NULL OR jsonb_array_length(receipt->'criteria')<>4 OR EXISTS(SELECT FROM jsonb_array_elements(receipt->'criteria') criterion WHERE jsonb_typeof(criterion->'met') IS DISTINCT FROM 'boolean') THEN RETURN base; END IF;
 SELECT count(*) INTO met_count FROM jsonb_array_elements(receipt->'criteria') criterion WHERE criterion->>'met'='true';factor_value:=met_count::numeric/4;
 RETURN base||jsonb_build_object('confirmedPoints',(base->>'confirmedPoints')::numeric+factor_value*15,'availableWeight',(base->>'availableWeight')::numeric+15,'factors',base->'factors'||jsonb_build_object('catalysts',jsonb_build_object('value',factor_value,'weight',15)));
END
;$function$;$create_vnext_current_deep_score_v1$;
 ALTER FUNCTION public.vnext_current_deep_score_v1 (jsonb,uuid,text) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_current_deep_score_v1 (jsonb,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
 ALTER TABLE public.vnext_provider_bindings_v1 DROP CONSTRAINT vnext_provider_bindings_v1_prompt_version_check;
 ALTER TABLE public.vnext_provider_bindings_v1 ADD CONSTRAINT vnext_provider_bindings_v1_prompt_version_check CHECK(prompt_version IN('vnext-research-worker-v1','vnext-research-worker-v2','vnext-research-worker-v3'));
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language language ON language.oid=p.prolang WHERE p.oid=to_regprocedure('public.vnext_thesis_command_v1(text,text,jsonb)') AND p.prokind='f' AND language.lanname='plpgsql' AND p.prorettype='jsonb'::regtype AND NOT p.proretset AND p.pronargs=3 AND p.proargtypes='25 25 3802'::oidvector AND p.proargnames=ARRAY['p_principal','p_command','p_request'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL) THEN RAISE EXCEPTION 'vnext_catalyst_original_profile_changed';END IF;
